import{_ as e,o as d,c as o,ak as a}from"./chunks/framework.Bh2SsxPX.js";const f=JSON.parse('{"title":"Main 聚合模块","description":"","frontmatter":{"title":"Main 聚合模块","prev":false,"next":false},"headers":[],"relativePath":"posts/docs/main/index.md","filePath":"posts/docs/main/index.md","lastUpdated":1777890485000}'),r={name:"posts/docs/main/index.md"};function i(n,t,l,c,s,b){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="anvillib-聚合模块" tabindex="-1">AnvilLib 聚合模块 <a class="header-anchor" href="#anvillib-聚合模块" aria-label="Permalink to “AnvilLib 聚合模块”">​</a></h1><p>该模块是 AnvilLib 的聚合模块，代表整个库的基座。它本身不包含功能代码，而是作为所有子模块的聚合入口，统一版本管理、构建发布与依赖协调。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to “项目结构”">​</a></h2><p>AnvilLib 采用多模块 Gradle 项目组织。根项目 <code>anvillib</code> 通过 <code>build.gradle</code> 统一配置所有子模块的构建信息。</p><p>目前已有的子模块：</p><table tabindex="0"><thead><tr><th>模块名称</th><th>功能</th></tr></thead><tbody><tr><td><code>anvillib-config-neoforge-26.1</code></td><td>配置系统（注解、反射、语言生成）</td></tr><tr><td><code>anvillib-codec-neoforge-26.1</code></td><td>Codec/StreamCodec 工具</td></tr><tr><td><code>anvillib-integration-neoforge-26.1</code></td><td>模组间集成系统</td></tr><tr><td><code>anvillib-moveable-entity-block-neoforge-26.1</code></td><td>活塞移动时保留方块实体数据</td></tr><tr><td><code>anvillib-network-neoforge-26.1</code></td><td>网络包抽象与自动注册</td></tr><tr><td><code>anvillib-recipe-neoforge-26.1</code></td><td>配方工具（谓词、概率物品等）</td></tr><tr><td><code>anvillib-registrum-neoforge-26.1</code></td><td>注册系统</td></tr><tr><td><code>anvillib-wheel-neoforge-26.1</code></td><td>轮盘菜单 UI 系统</td></tr><tr><td><code>anvillib-rendering-neoforge-26.1</code></td><td>功能不多的渲染库</td></tr><tr><td><code>anvillib-multiblock-neoforge-26.1</code></td><td>动态多方块系统</td></tr><tr><td><code>anvillib-util-neoforge-26.1</code></td><td>可共享的工具方法</td></tr></tbody></table><p>所有子模块均以 <code>jarJar</code> 方式包含，即内嵌到最终发布的 Jar 中，并使用 <code>api</code> 进行依赖传递，无需模组单独依赖。</p>',7)])])}const v=e(r,[["render",i]]);export{f as __pageData,v as default};
